const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const menu=$('#contents'), menuButton=$('#contentsButton');
menuButton.addEventListener('click',()=>{const open=menu.hidden;menu.hidden=!open;menuButton.setAttribute('aria-expanded',String(open));});
menu.addEventListener('click',e=>{if(e.target.closest('a')){menu.hidden=true;menuButton.setAttribute('aria-expanded','false');}});
document.addEventListener('click',e=>{if(!menu.contains(e.target)&&!menuButton.contains(e.target)){menu.hidden=true;menuButton.setAttribute('aria-expanded','false');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.hidden=true;menuButton.setAttribute('aria-expanded','false');}});
let scrollQueued=false;function updateProgress(){const max=document.documentElement.scrollHeight-innerHeight;$('.reading-progress span').style.width=(max?scrollY/max*100:0)+'%';scrollQueued=false;}addEventListener('scroll',()=>{if(!scrollQueued){requestAnimationFrame(updateProgress);scrollQueued=true;}},{passive:true});
const viewer=$('#screenDialog'), vi=$('#viewerImage');let viewerScale=1,viewerBase=1000,lastFocus;
function setZoom(){vi.style.width=Math.round(viewerBase*viewerScale)+'px';$('#zoomLevel').textContent=Math.round(viewerScale*100).toLocaleString('ar')+'٪';}
function openScreen(src,title){lastFocus=document.activeElement;$('#viewerTitle').textContent=title;vi.src=src;vi.alt=title;viewerScale=1;viewer.showModal();document.body.style.overflow='hidden';viewerBase=Math.min(viewer.clientWidth-48,1440);setZoom();$('.viewer-canvas').scrollTo(0,0);}
$('#closeViewer').onclick=()=>viewer.close();viewer.addEventListener('close',()=>{document.body.style.overflow='';lastFocus?.focus();});$('#zoomIn').onclick=()=>{viewerScale=Math.min(3,viewerScale+.25);setZoom();};$('#zoomOut').onclick=()=>{viewerScale=Math.max(.5,viewerScale-.25);setZoom();};$('#fitScreen').onclick=()=>{viewerScale=1;setZoom();};
document.addEventListener('click',e=>{const b=e.target.closest('[data-open]');if(b)openScreen(b.dataset.open,b.dataset.title||'شاشة من تصميم الراصد');});

const reduced=matchMedia('(prefers-reduced-motion: reduce)');
function switchSet(el,index,announce=true){const data=window.presentationSets[el.dataset.set];if(!Number.isInteger(index)||index<0||index>=data.length)throw new Error('حالة غير متاحة');const item=data[index];$$('[role=tab]',el).forEach((b,i)=>{b.setAttribute('aria-selected',String(i===index));b.tabIndex=i===index?0:-1;});const panel=$('[role=tabpanel]',el);panel.setAttribute('aria-labelledby',`tab-${el.dataset.set}-${index}`);$('.state-copy h3',el).textContent=item[2];$('.state-copy p',el).textContent=item[3];const img=$('.screen-surface img',el);img.src=A(item[1]);img.alt=item[0];const btn=$('[data-open]',el);btn.dataset.open=A(item[1]);btn.dataset.title=item[0];$('.screen-toolbar>span',el).textContent=item[0];const surface=$('.screen-surface',el);surface.scrollTop=0;surface.scrollLeft=0;if(announce)$('#announcer').textContent=item[2];el.dataset.current=String(index);if(el.dataset.set==='decisions'&&index>0){surface.scrollTop=surface.clientWidth*((index===2||index===3)?0.25:0.35);}if(el.dataset.set==='manager'){surface.scrollTop=index===1?surface.clientWidth*.32:index===2?surface.clientWidth*.53:0;}if(el.dataset.set==='team'){surface.scrollTop=index===1?surface.clientWidth*.43:index===2?surface.clientWidth*.2:0;}}
$$('[data-set]').forEach(el=>{el.dataset.current='0';el.addEventListener('click',e=>{const b=e.target.closest('[role=tab]');if(b)switchSet(el,Number(b.dataset.index));});el.addEventListener('keydown',e=>{const b=e.target.closest('[role=tab]');if(!b)return;const bs=$$('[role=tab]',el),i=bs.indexOf(b);let n;if(e.key==='ArrowLeft')n=(i+1)%bs.length;if(e.key==='ArrowRight')n=(i-1+bs.length)%bs.length;if(e.key==='Home')n=0;if(e.key==='End')n=bs.length-1;if(n!==undefined){e.preventDefault();switchSet(el,n);bs[n].focus();}});});
function setWalk(el,index){if(el.dataset.current===String(index))return;const data=window.presentationSets[el.dataset.walk],item=data[index];el.dataset.current=String(index);const img=$('.screen-surface img',el);img.src=A(item[1]);img.alt=item[0];$('.screen-toolbar>span',el).textContent=item[0];const b=$('[data-open]',el);b.dataset.open=A(item[1]);b.dataset.title=item[0];$('.count-current',el).textContent=(index+1).toLocaleString('ar')+' / '+data.length.toLocaleString('ar');$$('.walk-dots button',el).forEach((b,i)=>{b.classList.toggle('active',i===index);b.setAttribute('aria-pressed',String(i===index));});$$('.walk-step',el).forEach((s,i)=>s.classList.toggle('active',i===index));$('.screen-surface',el).scrollTop=0;}
const walks=$$('[data-walk]');walks.forEach(el=>{setWalk(el,0);el.addEventListener('click',e=>{const b=e.target.closest('.walk-dots button');if(!b)return;const i=Number(b.dataset.step),step=$$('.walk-step',el)[i];setWalk(el,i);const visual=$('.walk-visual',el);const mobile=innerWidth<=800;if(mobile)return;const target=scrollY+step.getBoundingClientRect().top-(mobile?visual.offsetHeight+95:innerHeight*.25);window.scrollTo({top:target,behavior:reduced.matches?'instant':'smooth'});});});
function syncWalks(){if(innerWidth<=800)return;walks.forEach(el=>{const r=el.getBoundingClientRect();if(r.bottom<0||r.top>innerHeight)return;const target=innerWidth<=800?innerHeight*.85:innerHeight*.5;const steps=$$('.walk-step',el);let active=0;let closest=Infinity;steps.forEach((step,i)=>{const s=step.getBoundingClientRect();const distance=Math.abs((s.top+s.bottom)/2-target);if(distance<closest){closest=distance;active=i;}});setWalk(el,active);});}
let walkPending=false;addEventListener('scroll',()=>{if(walkPending)return;walkPending=true;requestAnimationFrame(()=>{syncWalks();walkPending=false;});},{passive:true});addEventListener('resize',syncWalks);
const models={advisor:[['المستخدم','يشارك هدفه','خبرة وتفضيلات وقيود واضحة'],['المستشار','يفهم الطلب','يراجع الملف ويسأل عند الحاجة'],['الراصد','تبحث وتختار','فرص منتقاة بدل قائمة ضخمة'],['الفرصة','تصل مع تفسير','لماذا اختارها المستشار؟'],['المستخدم','يعطي رأيه','اهتمام أو سؤال أو عدم ملاءمة'],['المستشار','يواصل الرحلة','متابعة بسياق أحدث']],traditional:[['المستخدم','يبحث','يبدأ من مواقع الوظائف'],['المستخدم','يفلتر','يفرز النتائج المتاحة'],['المستخدم','يقيّم','يفهم الملاءمة بنفسه'],['المستخدم','يقدّم','يرسل الطلبات'],['المستخدم','يتابع','يجمع حالاتها يدويًا'],['المستخدم','يكرر','يبدأ البحث مرة أخرى']]};
function setModel(model){if(!models[model])throw new Error('نموذج غير متاح');$('#modelStage').innerHTML=models[model].map((n,i)=>`<article class="model-node ${model==='advisor'&&[1,2,5].includes(i)?'human':''}" style="--i:${i}"><span>${n[0]}</span><h3>${n[1]}</h3><p>${n[2]}</p></article>`).join('');$$('[data-model]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.model===model)));}$$('[data-model]').forEach(b=>b.addEventListener('click',()=>setModel(b.dataset.model)));setModel('advisor');
$('#compareToggle').addEventListener('click',()=>{const on=$('.before-after').dataset.after!=='true';$('.before-after').dataset.after=String(on);$('#compareToggle').setAttribute('aria-pressed',String(on));$('#compareToggle').textContent=on?'أعد التركيز على البداية →':'اعرض التحوّل ←';});
const ro=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('seen');ro.unobserve(e.target);}}),{threshold:.08});$$('.section-lead,.proof-item,.value-list>a,.section>h2').forEach(el=>{el.classList.add('reveal');ro.observe(el);});if(!reduced.matches)document.body.classList.add('js-motion');
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'show_presentation_state',title:'استكشاف حالة تصميمية',description:'Switch a presentation gallery to an existing Figma screen state. Changes only the local presentation; does not submit a request or operate the product.',inputSchema:{type:'object',properties:{gallery:{type:'string',enum:Object.keys(window.presentationSets).filter(k=>!['home','onboarding'].includes(k))},index:{type:'integer',minimum:0}},required:['gallery','index'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.gallery!=='string'||!Number.isInteger(input.index))throw new Error('Invalid state');const el=$(`[data-set="${CSS.escape(input.gallery)}"]`);if(!el)throw new Error('Gallery not found');switchSet(el,input.index);el.scrollIntoView({behavior:'instant',block:'start'});return{gallery:input.gallery,index:input.index,title:window.presentationSets[input.gallery][input.index][2]};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
updateProgress();
function positionMobileImage(img){const surface=img.closest('.screen-surface');if(innerWidth<=800&&surface&&!img.closest('.phone-screen'))surface.scrollLeft=-(surface.scrollWidth-surface.clientWidth)*.7;}
$$('.screen-surface img').forEach(img=>{img.addEventListener('load',()=>positionMobileImage(img));if(img.complete)positionMobileImage(img);});
